// core/i18n.js — GUI 语言包（#89 T1a/T1b·方案 docs/方案-89语言包-2026-11-05.md §技术设计 1-3；T1b=shell.js 壳层文案入典）
//   zh/en 扁平字典（键 view.module.key）+ t(key, params?) 插值 + getLang()/setLang(lang)。
//   en 缺键回落 zh 值（P9）；切换 = 双写落定后整页 reload（P1·无热更新路径）：
//     ① localStorage 快键 gui13.uiLang（老板原话"localStorage 记忆"·兼解 FOUC/离线·P8/P11）
//     ② readAgg 取全量 pref 合并 uiLang 后 saveAggAwait（N3 约束：子键整体替换须带全量·防抹 uiFont 等）
//   getLang 启动初值＝快键‖服务端 pref.uiLang（合法才用·N3 非法视同不存在）‖zh；
//   服务端合法值与快键不同 → 以服务端为准并回写快键（跨机/跨浏览器一致）。
//   不 import views（core 层纪律）；失败 toast 走动态 import ui/toast（同 server_storage.js:518 先例）。
import { readAgg, saveAggAwait, SETTINGS_JSON } from "./server_storage.js";

// localStorage 快键（设置页 loadPref 的 N2 回落同键·single source）
export const LANG_STORAGE_KEY = "gui13.uiLang";

// N3：合法语言值仅 zh|en——非法视同不存在
export function isValidLang(v) {
  return v === "zh" || v === "en";
}

