  "guide.s0.title": "⓪ Start the engine",
  "guide.s0.body": "Video generation runs on the local engine: click Start Engine in Settings, or click the engine chip at the bottom of the left sidebar, and wait for the status light to turn green before moving on. You can browse the UI before the light turns green — generation just won't run.",
  "guide.s1.title": "① Create a project",
  "guide.s1.body": "On the portal page click the dashed New Project box → enter a project name → you land on the setup page automatically.",
  "guide.s2.title": "② Set parameters / write prompts",
  "guide.s2.body": "In the setup TAB pick global parameters such as aspect ratio and quality; write prompts on segment cards — type @ to reference asset-library cards.",
  "guide.s3.title": "③ Submit to the engine",
  "guide.s3.body": "Click Run project at the bottom to submit the task; watch progress and completion in the sidebar bell (notification center).",
  "guide.s4.title": "④ Edit",
  "guide.s4.body": "Trim clips in the edit TAB: Ctrl+B split, Ctrl+C / Ctrl+V copy-paste, Ctrl+Z undo — full key list: press ?, or see the bottom bar of the Ctrl+K search modal.",
