// 取映射显示词：zh（或表未覆盖/未知域）→ 原值直通；en → 查表命中返回映射·否则原值。
export function pickDisplay(mapName, zhValue) {
  if (getLang() !== "en") return zhValue;
  const m = MAPS[mapName];
  const v = m ? m[zhValue] : undefined;
  return typeof v === "string" ? v : zhValue;
}

// ===== 取词 =====
//   当前语言查 en → 缺键回落 zh → 双缺返回键本身（键自检脚本兜 0 未知键）。
//   params 插值：{name} 占位，缺参保留占位原样。
export function t(key, params) {
  const lang = getLang();
  const dict = LANGS[lang];
  let v = dict && typeof dict[key] === "string" ? dict[key] : ZH[key];
  if (typeof v !== "string") return key;
  if (!params) return v;
  return v.replace(/\{(\w+)\}/g, (m, name) =>
    params[name] != null ? String(params[name]) : m
  );
}

// ===== 当前语言（双源：localStorage 快键 ‖ 服务端 pref.uiLang·N3 合法性校验）=====
function _ls() {
  return typeof globalThis !== "undefined" && globalThis.localStorage
    ? globalThis.localStorage
    : null;
}

export function getLang() {
  const ls = _ls();
  let quick = null;
  if (ls) {
    try { quick = isValidLang(ls.getItem(LANG_STORAGE_KEY)) ? ls.getItem(LANG_STORAGE_KEY) : null; }
    catch (_e) { quick = null; }
  }
  let server = null;
  const pref = readAgg(SETTINGS_JSON, "pref");
  if (pref && typeof pref === "object" && isValidLang(pref.uiLang)) server = pref.uiLang;
  // 服务端合法值与快键不同 → 以服务端为准并回写快键（跨机一致·方案 §技术设计 1）
  if (server && server !== quick) {
    if (ls) { try { ls.setItem(LANG_STORAGE_KEY, server); } catch (_e) { /* 忽略 */ } }
    return server;
  }
  return quick || "zh";
}

// ===== 切换语言（双写落定 → dataset.lang → reload·P1）=====
//   返回 Promise<boolean>（服务端落定结果）；失败不阻断切换（快键已写·仍 reload·降级③）。
export async function setLang(lang) {
  if (!isValidLang(lang)) return false;
  const ls = _ls();
  if (ls) { try { ls.setItem(LANG_STORAGE_KEY, lang); } catch (_e) { /* 无 localStorage → 只走服务端/内存 */ } }
  // N3 执行约束：writeAgg 子键整体替换 → 先 readAgg 取全量 pref 合并 uiLang（防抹 uiFont/videoModel/chatTimeoutSec）
  const cur = readAgg(SETTINGS_JSON, "pref");
  const merged = { ...(cur && typeof cur === "object" && !Array.isArray(cur) ? cur : {}), uiLang: lang };
  let saved = false;
  try { saved = await saveAggAwait(SETTINGS_JSON, "pref", merged); }
  catch (_e) { saved = false; }
  if (!saved) {
    try {
      const { showToast } = await import("../ui/toast.js");   // core 不静态依赖 ui（同 server_storage 先例）
      showToast("warn", t("i18n.saveFailed"));
    } catch (_e) { /* toast 通道不可用（测试环境）→ 忽略 */ }
  }
  if (typeof document !== "undefined" && document.documentElement) {
    document.documentElement.dataset.lang = lang;
    syncDocLang(lang);   // #92 B6：文档语言属性随语言态（QQ 自带翻译缓解·data-lang 逻辑零改）
  }
  if (typeof location !== "undefined" && typeof location.reload === "function") location.reload();
  return saved;
}

// ===== 文档语言属性同步（#92 B6·QQ 浏览器自带翻译/扩展改写页面文本缓解）=====
//   document.documentElement.lang 随语言态（en→en / zh→zh-CN）；与 dataset.lang 双轨并存
//   （boot 快键/setLang 写 dataset.lang 的既有逻辑零改）。模块加载与 setLang 双路径同步；
//   Node（无 document）零副作用。
function syncDocLang(lang) {
  if (typeof document === "undefined" || !document.documentElement) return;
  document.documentElement.lang = lang === "en" ? "en" : "zh-CN";
}
if (typeof document !== "undefined" && document.documentElement) syncDocLang(getLang());
